<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free PDF Page Extractor','description'=>'Select PDF page numbers and create a new PDF in your browser.','url'=>'https://smarttoolz.in/tools/pdf-page-extractor/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><h1>PDF Page Extractor</h1><p>Extract selected pages from a PDF locally.</p></section><section class="tool-workspace"><div class="tool-panel"><input id="f" type="file" accept="application/pdf"><input id="p" placeholder="Pages e.g. 1,3-5"><button id="go" class="tool-btn">Extract Pages</button><p id="o">Uses your browser only.</p></div></section></main><script src="https://cdn.jsdelivr.net/npm/pdf-lib@1.17.1/dist/pdf-lib.min.js"></script><script>go.onclick=async()=>{let f=document.getElementById('f').files[0];if(!f){o.textContent='Choose a PDF.';return}try{let src=await PDFLib.PDFDocument.load(await f.arrayBuffer()),out=await PDFLib.PDFDocument.create(),ids=[];p.value.split(',').forEach(s=>{let q=s.trim().split('-').map(Number);if(q.length===1)ids.push(q[0]-1);else for(let i=q[0];i<=q[1];i++)ids.push(i-1)});ids=ids.filter(i=>i>=0&&i<src.getPageCount());let pages=await out.copyPages(src,ids);pages.forEach(x=>out.addPage(x));let bytes=await out.save(),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([bytes],{type:'application/pdf'}));a.download='extracted-pages.pdf';a.click();o.textContent=`Created ${pages.length} page PDF.`}catch(e){o.textContent='Could not process this PDF.'}}</script><?php smarttoolz_tool_page_end(); ?>